  g=SecretFixture("EX1_130");var attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Health==30&&attacker.Health==3&&g.Players[0].Board.Count==0&&g.Players[0].SecretCount==0,"Noble Sacrifice redirects attack to 2/1 defender");
  g=SecretFixture("EX1_289");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Health==30&&g.Players[0].Armor==4,"Ice Barrier grants armor before attack damage");
  g=SecretFixture("EX1_594");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[1].Board.Count==0&&g.Players[0].Health==30,"Vaporize destroys attacking minion before damage");
  g=SecretFixture("EX1_611");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Health==30&&g.Players[1].Board.Count==0&&g.Players[1].Hand.Single().CostAdjustment==2&&g.HandCost(1,g.Players[1].Hand.Single())==6,"Freezing Trap returns attacker with per-instance extra cost");
