  g=SecretFixture("EX1_533");g.Players[1].ClassId="WARRIOR";g.EquipRaw(1,"VAN_CS2_106",3,2,false);g.Attack(1,0,new MatchTarget(0));Check(g.Players[0].SecretCount==1,"Misdirection remains when there is no other character");g=SecretFixture("EX1_533");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Health==30&&g.Players[1].Health==26,"Misdirection can redirect minion attack to its own hero");
