  g=SecretFixture("EX1_136");target=g.Summon(0,"VAN_EX1_556");g.Play(1,Inject(g,"CS2_029",1),new MatchTarget(0,target.Id));Check(g.Players[0].Board.Count==2&&g.Players[0].Board.Single(u=>u.CardId=="VAN_EX1_556").Health==1&&g.Players[0].SecretCount==0,"Redemption resurrects at one health while preserving deathrattle token");
  g=MatchFixture();g.Play(0,Inject(g,"EX1_295"));g.Players[0].Health=1;g.Damage(new MatchTarget(0),1);g.Cleanup();Check(g.Finished&&g.Players[0].SecretCount==1,"Secrets do not trigger during their owner's turn");
  g=SecretFixture("EX1_294","tt_010","EX1_130","EX1_554");for(int n=0;n<7;n++)g.Summon(0,"VAN_CS2_231");g.Play(1,Inject(g,"CS2_182",1));Check(g.Players[0].SecretCount==4,"Full board does not consume summon-only secrets");target=g.Players[0].Board[0];g.Play(1,Inject(g,"CS2_024",1),new MatchTarget(0,target.Id));Check(g.Players[0].SecretCount==4,"Spellbender stays armed with no free slot");
  g=SecretFixture("EX1_611");for(int n=0;n<10;n++)Inject(g,"CS2_231",1);attacker=g.Summon(1,"VAN_EX1_556");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[1].Hand.Count==10&&g.Players[1].Board.Single().CardId=="VAN_skele21"&&g.Players[0].Health==30,"Full-hand Freezing Trap destroys returned minion and resolves deathrattle");
  g=SecretFixture("EX1_130","EX1_611");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Board.Single().CardId=="GAME_DEFENDER"&&g.Players[0].SecretCount==0,"Noble then Freezing consumes both and preserves unhit defender");g=SecretFixture("EX1_611","EX1_130");attacker=g.Summon(1,"VAN_CS2_182");attacker.SummonTurn=0;g.Attack(1,attacker.Id,new MatchTarget(0));Check(g.Players[0].Board.Count==0&&g.Players[0].SecretCount==1,"Freezing before Noble cancels later attack trigger");
  g=SecretFixture("EX1_609","EX1_294");g.Play(1,Inject(g,"CS2_231",1));Check(g.Players[1].Board.Count==0&&g.Players[0].Board.Count==0&&g.Players[0].SecretCount==1,"Snipe killing played minion prevents later Mirror Entity");
  g=SecretFixture("EX1_136");target=g.Summon(0,"VAN_CS2_231");attacker=g.Summon(0,"VAN_CS2_182");g.Play(1,Inject(g,"CS2_029",1),new MatchTarget(0,target.Id));Check(g.Players[0].Board[0].CardId=="VAN_CS2_231"&&g.Players[0].Board[1].Id==attacker.Id,"Redemption restores death position relative to survivors");
  PreviewSecretPresentationScope(folder);VerifySecretTcp();var cards=catalog.Deckable(catalog.Pool("classic-2014")).Select(c=>new{Id=c.Id,Name=c.Name,Supported=matchRules.Supports(c)}).ToArray();Check(cards.Count(c=>c.Supported)==302,"Coverage now 302 of 382");JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=302,TotalCards=382,Cards=cards,Scope="Classic secret verification"});File.WriteAllText(Path.Combine(folder,"secret-verification.txt"),"PASS: "+(checks-before)+" secret assertions, all fifteen cards, ordered triggers, identity masking, loopback TCP and WPF previews.");
