 void VerifySecretTcp(){if(!VerificationRun.Network)return;LeaveLan();var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Secret TCP peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Secret host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Secret peers start match");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=10;}int secret=Inject(g,"EX1_287");DoMatch("play",secret);PumpLan(()=>guest.match.Players[0].SecretCount==1,"Anonymous secret count reaches guest");Check(!guest.match.Log.Any(l=>l.Contains("法术反制"))&&guest.match.VisualEvents.All(e=>e.CardId!="VAN_EX1_287"),"Actual TCP guest cannot see secret identity");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest secret trigger turn starts");g.Players[1].Mana=10;int fire=Inject(g,"CS2_029",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Guest private spell arrives");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].SecretCount==0,"Guest spell triggers authoritative secret");Check(g.Players[0].Health==30&&guest.match.Players[0].Health==30&&guest.match.Log.Any(l=>l.Contains("奥秘触发：法术反制")),"Countered effect and revealed identity synchronize");}finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
